#!/usr/bin/env python3 from __future__ import annotations import argparse, csv, math from collections import defaultdict from pathlib import Path from typing import Any import numpy as np import torch import torch.nn.functional as F from PIL import Image from skimage.metrics import structural_similarity ALIASES = { "dataset": ["dataset", "dataset_name", "set"], "method": ["method", "method_name", "model"], "sample_id": ["sample_id", "id", "name", "filename"], "a": ["a", "A", "image_a", "image_a_path", "a_path", "source_a", "input_a", "edit_image_0"], "b": ["b", "B", "image_b", "image_b_path", "b_path", "source_b", "input_b", "edit_image_1"], "gt": ["gt", "GT", "image", "target", "hq", "gt_path", "target_path", "image_path"], "pred": ["fused", "prediction", "pred", "output", "result", "fused_path", "prediction_path", "pred_path", "output_path"], "fa": ["focus_a", "focusA", "fa", "focus_map_a", "focus_a_path", "focus_map_a_path", "focus_image_a", "edit_image_2", "m_a"], "fb": ["focus_b", "focusB", "fb", "focus_map_b", "focus_b_path", "focus_map_b_path", "focus_image_b", "edit_image_3", "m_b"], } def parse_args(): p = argparse.ArgumentParser(description="Four-region MFIF evaluator: GT + No-GT protocols") p.add_argument("--manifest", required=True) p.add_argument("--output-dir", required=True) p.add_argument("--root", default="") p.add_argument("--sharp-threshold", type=float, default=0.70) p.add_argument("--blur-threshold", type=float, default=0.30) p.add_argument("--erode-radius", type=int, default=-1, help="-1 => max(2, round(min(H,W)/256))") p.add_argument("--patch-size", type=int, default=64) p.add_argument("--patch-stride", type=int, default=32) p.add_argument("--g-patch-min-coverage", type=float, default=0.80) p.add_argument("--g-rsr-psnr-margin", type=float, default=0.20) p.add_argument("--device", default="cuda") p.add_argument("--lpips-net", default="alex", choices=["alex", "vgg", "squeeze"]) p.add_argument("--no-lpips", action="store_true") for x in ["dataset", "method", "id", "a", "b", "gt", "pred", "focus-a", "focus-b"]: p.add_argument(f"--col-{x}", default="") return p.parse_args() def finite(x): try: return math.isfinite(float(x)) except Exception: return False def nanmean(xs): ys = [float(x) for x in xs if finite(x)] return float(np.mean(ys)) if ys else float("nan") def find_col(fields, explicit, key, required): if explicit: if explicit not in fields: raise KeyError(f"column {explicit!r} not found; columns={fields}") return explicit for c in ALIASES[key]: if c in fields: return c if required: raise KeyError(f"cannot detect column for {key}; columns={fields}") return None def resolve(root: Path, raw: Any): if raw is None: return None s = str(raw).strip() if not s or s.lower() in {"none", "nan", "null"}: return None p = Path(s) return p if p.is_absolute() else root / p def load_rgb(p: Path): if not p.is_file(): raise FileNotFoundError(p) return np.asarray(Image.open(p).convert("RGB"), np.float32) / 255.0 def load_gray(p: Path): if not p.is_file(): raise FileNotFoundError(p) if p.suffix.lower() == ".npy": x = np.squeeze(np.load(p)).astype(np.float32) if x.ndim != 2: raise ValueError(f"focus map must be 2D: {p} {x.shape}") if float(np.nanmax(x)) > 1.5: x /= 255.0 return np.clip(x, 0, 1) return np.asarray(Image.open(p).convert("L"), np.float32) / 255.0 def resize_rgb(x, hw, mode): h, w = hw if x.shape[:2] == (h, w): return x im = Image.fromarray(np.clip(np.round(x*255), 0, 255).astype(np.uint8), "RGB") return np.asarray(im.resize((w, h), mode), np.float32) / 255.0 def resize_gray(x, hw): h, w = hw if x.shape[:2] == (h, w): return x im = Image.fromarray(np.clip(np.round(x*255), 0, 255).astype(np.uint8), "L") return np.asarray(im.resize((w, h), Image.Resampling.BILINEAR), np.float32) / 255.0 def erode(mask, r): if r <= 0: return mask.astype(bool) x = torch.from_numpy(mask.astype(np.float32))[None,None] k = 2*r+1 y = 1 - F.max_pool2d(1-x, k, stride=1, padding=r) return (y[0,0].numpy() > .5) def gray(x): return (0.299*x[...,0] + 0.587*x[...,1] + 0.114*x[...,2]).astype(np.float32) SX = np.array([[-1,0,1],[-2,0,2],[-1,0,1]], np.float32)/8.0 SY = SX.T.copy() LAP = np.array([[0,1,0],[1,-4,1],[0,1,0]], np.float32) def conv(g, k): x = torch.from_numpy(g)[None,None] kk = torch.from_numpy(k)[None,None] return F.conv2d(x, kk, padding=(k.shape[0]//2, k.shape[1]//2))[0,0].numpy() def sobel(x): g = gray(x); gx = conv(g,SX); gy = conv(g,SY) return np.sqrt(gx*gx + gy*gy + 1e-12) def lapabs(x): return np.abs(conv(gray(x), LAP)) def blur_gray(g, sigma=1.5): r = max(1, int(round(3*sigma))) xs = torch.arange(-r, r+1, dtype=torch.float32) k = torch.exp(-(xs*xs)/(2*sigma*sigma)); k /= k.sum() x = torch.from_numpy(g)[None,None] x = F.conv2d(x, k[None,None,None,:], padding=(0,r)) x = F.conv2d(x, k[None,None,:,None], padding=(r,0)) return x[0,0].numpy() def hfabs(x): g = gray(x) return np.abs(g - blur_gray(g)) def masked_mean(x, m): if int(m.sum()) == 0: return float("nan") return float(np.mean(x[m])) def masked_mse(a,b,m): if int(m.sum()) == 0: return float("nan") return float(np.mean(((a-b)**2)[m,:])) def masked_mae(a,b,m): if int(m.sum()) == 0: return float("nan") return float(np.mean(np.abs(a-b)[m,:])) def psnr_from_mse(m): if not finite(m): return float("nan") if m <= 1e-12: return 120.0 return float(-10*math.log10(m)) def ssim_map(a,b): _, sm = structural_similarity(a,b,data_range=1.0,channel_axis=2,full=True, gaussian_weights=True,sigma=1.5,use_sample_covariance=False) if sm.ndim == 3: sm = sm.mean(2) return sm.astype(np.float32) class LP: def __init__(self, device="cuda", net="alex", enabled=True): self.enabled = enabled self.device = torch.device(device if device != "cuda" or torch.cuda.is_available() else "cpu") self.model = None if enabled: try: import lpips except Exception as e: raise RuntimeError("install lpips or use --no-lpips") from e self.model = lpips.LPIPS(net=net, spatial=True).to(self.device).eval() self.model.requires_grad_(False) def map(self,a,b): if not self.enabled: return None ta = torch.from_numpy(a.transpose(2,0,1))[None].to(self.device)*2-1 tb = torch.from_numpy(b.transpose(2,0,1))[None].to(self.device)*2-1 with torch.inference_mode(): y = self.model(ta,tb) y = F.interpolate(y, size=a.shape[:2], mode="bilinear", align_corners=False) return y[0,0].float().cpu().numpy() def masked(self, lm, m): if lm is None or int(m.sum()) == 0: return float("nan") return float(np.mean(lm[m])) def crop(self,a,b): if not self.enabled: return float("nan") ta = torch.from_numpy(a.transpose(2,0,1))[None].to(self.device)*2-1 tb = torch.from_numpy(b.transpose(2,0,1))[None].to(self.device)*2-1 with torch.inference_mode(): y = self.model(ta,tb) return float(y.mean().item()) def metrics(pred, ref, mask, sm, lm, lp): mse = masked_mse(pred,ref,mask) return { "psnr": psnr_from_mse(mse), "ssim": masked_mean(sm,mask), "lpips": lp.masked(lm,mask), "mae": masked_mae(pred,ref,mask), "mse": mse, } def put(row, prefix, d): for k,v in d.items(): row[f"{prefix}_{k}"] = v def regions(fa,fb,sharp,blur): AS, ABR = fa >= sharp, fa <= blur BS, BBR = fb >= sharp, fb <= blur r = { "a": AS & BBR, "b": ABR & BS, "ab": AS & BS, "g": ABR & BBR, } r["uncertain"] = ~(r["a"] | r["b"] | r["ab"] | r["g"]) return r def g_nogt(pred,a,b,m): if int(m.sum()) == 0: keys = ["sobel_pred","sobel_a","sobel_b","sobel_gain_best_src", "laplacian_pred","laplacian_a","laplacian_b","laplacian_gain_best_src", "highfreq_pred","highfreq_a","highfreq_b","highfreq_gain_best_src"] return {f"g_{k}": float("nan") for k in keys} sp,sa,sb = [masked_mean(z,m) for z in [sobel(pred),sobel(a),sobel(b)]] lp,la,lb = [masked_mean(z,m) for z in [lapabs(pred),lapabs(a),lapabs(b)]] hp,ha,hb = [masked_mean(z,m) for z in [hfabs(pred),hfabs(a),hfabs(b)]] return { "g_sobel_pred":sp, "g_sobel_a":sa, "g_sobel_b":sb, "g_sobel_gain_best_src":sp-max(sa,sb), "g_laplacian_pred":lp, "g_laplacian_a":la, "g_laplacian_b":lb, "g_laplacian_gain_best_src":lp-max(la,lb), "g_highfreq_pred":hp, "g_highfreq_a":ha, "g_highfreq_b":hb, "g_highfreq_gain_best_src":hp-max(ha,hb), } def patches(h,w,p,s): if h < p or w < p: return ys = list(range(0,h-p+1,s)); xs = list(range(0,w-p+1,s)) if ys[-1] != h-p: ys.append(h-p) if xs[-1] != w-p: xs.append(w-p) for y in ys: for x in xs: yield y,x def g_rsr(pred,a,b,gt,m,lp,patch,stride,mincov,margin): valid=success=0 h,w=m.shape for y,x in patches(h,w,patch,stride): mm=m[y:y+patch,x:x+patch] if float(mm.mean()) < mincov: continue pp=pred[y:y+patch,x:x+patch]; aa=a[y:y+patch,x:x+patch] bb=b[y:y+patch,x:x+patch]; gg=gt[y:y+patch,x:x+patch] pps=psnr_from_mse(masked_mse(pp,gg,mm)); aps=psnr_from_mse(masked_mse(aa,gg,mm)); bps=psnr_from_mse(masked_mse(bb,gg,mm)) if lp.enabled: pl=lp.crop(pp,gg); al=lp.crop(aa,gg); bl=lp.crop(bb,gg) lpok = pl < min(al,bl) else: lpok=True valid += 1 if pps > max(aps,bps)+margin and lpok: success += 1 return (success/valid if valid else float("nan")), valid, success def write_csv(path, rows): path.parent.mkdir(parents=True, exist_ok=True) keys=[]; seen=set() for r in rows: for k in r: if k not in seen: seen.add(k); keys.append(k) with path.open("w",newline="",encoding="utf-8") as f: w=csv.DictWriter(f,fieldnames=keys); w.writeheader(); w.writerows(rows) def summarize(rows): groups=defaultdict(list) for r in rows: groups[(r["dataset"],r["method"])].append(r) outs=[] skip={"dataset","method","sample_id","a_path","b_path","gt_path","pred_path","focus_a_path","focus_b_path", "g_valid_patch_count","g_success_patch_count"} for (ds,me),rs in groups.items(): o={"dataset":ds,"method":me,"n":len(rs)} nums=set() for r in rs: for k,v in r.items(): if k not in skip and isinstance(v,(int,float,np.integer,np.floating)): nums.add(k) for k in sorted(nums): o[k+"_mean"] = nanmean([r.get(k,float("nan")) for r in rs]) nv=sum(int(r.get("g_valid_patch_count",0)) for r in rs); ns=sum(int(r.get("g_success_patch_count",0)) for r in rs) o["g_rsr_pooled"] = ns/nv if nv else float("nan") o["g_valid_patch_count_total"] = nv; o["g_success_patch_count_total"] = ns outs.append(o) return outs def main(): args=parse_args(); mf=Path(args.manifest); out=Path(args.output_dir) root=Path(args.root) if args.root else mf.parent with mf.open("r",encoding="utf-8-sig",newline="") as f: rd=csv.DictReader(f); fields=rd.fieldnames or []; recs=list(rd) cd=find_col(fields,args.col_dataset,"dataset",False); cm=find_col(fields,args.col_method,"method",False); ci=find_col(fields,args.col_id,"sample_id",False) ca=find_col(fields,args.col_a,"a",True); cb=find_col(fields,args.col_b,"b",True); cp=find_col(fields,args.col_pred,"pred",True) cfa=find_col(fields,args.col_focus_a,"fa",True); cfb=find_col(fields,args.col_focus_b,"fb",True); cgt=find_col(fields,args.col_gt,"gt",False) print(f"[MANIFEST] {mf}\n[ROWS] {len(recs)}\n[COLUMNS] A={ca} B={cb} GT={cgt} PRED={cp} FA={cfa} FB={cfb}") lp=LP(args.device,args.lpips_net,not args.no_lpips); rows=[] for i,it in enumerate(recs): ap=resolve(root,it[ca]) bp=resolve(root,it[cb]) pp=resolve(root,it[cp]) fap=resolve(root,it[cfa]) fbp=resolve(root,it[cfb]) gtp=resolve(root,it[cgt]) if cgt else None mode=str(it.get("fused_mode","")).strip().lower() virtual_pred=None if mode in ( "avgblend", "avg_blend", "avg blend", ): virtual_pred="avgblend" elif mode in ( "no_generation", "nogeneration", "w/o generation", "wo generation", ): virtual_pred="nogeneration" if virtual_pred is None: if pp is None: raise RuntimeError( f"row {i}: missing fused path method={it.get('method')} mode={mode}" ) if any(x is None for x in [ap,bp,fap,fbp]): raise RuntimeError( f"row {i}: missing required path method={it.get('method')} mode={mode}" ) a=load_rgb(ap); h,w=a.shape[:2] b=resize_rgb(load_rgb(bp),(h,w),Image.Resampling.BICUBIC) if virtual_pred=="avgblend": pred=0.5*(a+b) elif virtual_pred=="nogeneration": pred=a.copy() else: pred=resize_rgb(load_rgb(pp),(h,w),Image.Resampling.BICUBIC) fa=resize_gray(load_gray(fap),(h,w)); fb=resize_gray(load_gray(fbp),(h,w)) gt=resize_rgb(load_rgb(gtp),(h,w),Image.Resampling.LANCZOS) if gtp is not None and gtp.is_file() else None raw=regions(fa,fb,args.sharp_threshold,args.blur_threshold) er=args.erode_radius if args.erode_radius>=0 else max(2,int(round(min(h,w)/256.0))) masks={k:(erode(v,er) if k!="uncertain" else v) for k,v in raw.items()} row={ "dataset":it[cd] if cd else "dataset", "method":it[cm] if cm else "method", "sample_id":it[ci] if ci else pp.stem, "a_path":str(ap),"b_path":str(bp),"gt_path":str(gtp) if gtp else "","pred_path":str(pp),"focus_a_path":str(fap),"focus_b_path":str(fbp), "height":h,"width":w,"erode_radius":er, "a_raw_ratio":float(raw["a"].mean()),"b_raw_ratio":float(raw["b"].mean()),"ab_raw_ratio":float(raw["ab"].mean()),"g_raw_ratio":float(raw["g"].mean()),"uncertain_raw_ratio":float(raw["uncertain"].mean()), "a_eval_ratio":float(masks["a"].mean()),"b_eval_ratio":float(masks["b"].mean()),"ab_eval_ratio":float(masks["ab"].mean()),"g_eval_ratio":float(masks["g"].mean()), "a_eval_pixels":int(masks["a"].sum()),"b_eval_pixels":int(masks["b"].sum()),"ab_eval_pixels":int(masks["ab"].sum()),"g_eval_pixels":int(masks["g"].sum()), } # No-GT A/B/AB preservation-transfer protocol. sma=ssim_map(pred,a); smb=ssim_map(pred,b); lma=lp.map(pred,a); lmb=lp.map(pred,b) put(row,"a_src",metrics(pred,a,masks["a"],sma,lma,lp)) put(row,"b_src",metrics(pred,b,masks["b"],smb,lmb,lp)) put(row,"ab_src_a",metrics(pred,a,masks["ab"],sma,lma,lp)) put(row,"ab_src_b",metrics(pred,b,masks["ab"],smb,lmb,lp)) preserve=masks["a"]|masks["ab"] put(row,"preserve_src",metrics(pred,a,preserve,sma,lma,lp)) row.update(g_nogt(pred,a,b,masks["g"])) if gt is not None: smg=ssim_map(pred,gt); lmg=lp.map(pred,gt) for reg in ["a","b","ab","g"]: put(row,f"{reg}_gt",metrics(pred,gt,masks[reg],smg,lmg,lp)) row["g_sobel_error"] = masked_mean(np.abs(sobel(pred)-sobel(gt)),masks["g"]) row["g_laplacian_error"] = masked_mean(np.abs(lapabs(pred)-lapabs(gt)),masks["g"]) smagt=ssim_map(a,gt); smbgt=ssim_map(b,gt); lmagt=lp.map(a,gt); lmbgt=lp.map(b,gt) ga=metrics(a,gt,masks["g"],smagt,lmagt,lp); gb=metrics(b,gt,masks["g"],smbgt,lmbgt,lp) for k,v in ga.items(): row[f"g_src_a_gt_{k}"]=v for k,v in gb.items(): row[f"g_src_b_gt_{k}"]=v row["g_psnr_gain_best_src"] = row["g_gt_psnr"]-max(ga["psnr"],gb["psnr"]) if finite(row["g_gt_psnr"]) and finite(ga["psnr"]) and finite(gb["psnr"]) else float("nan") row["g_lpips_gain_best_src"] = min(ga["lpips"],gb["lpips"])-row["g_gt_lpips"] if finite(row["g_gt_lpips"]) and finite(ga["lpips"]) and finite(gb["lpips"]) else float("nan") rsr,nv,ns=g_rsr(pred,a,b,gt,masks["g"],lp,args.patch_size,args.patch_stride,args.g_patch_min_coverage,args.g_rsr_psnr_margin) row["g_rsr"]=rsr; row["g_valid_patch_count"]=nv; row["g_success_patch_count"]=ns else: for reg in ["a","b","ab","g"]: for k in ["psnr","ssim","lpips","mae","mse"]: row[f"{reg}_gt_{k}"]=float("nan") for k in ["g_sobel_error","g_laplacian_error","g_psnr_gain_best_src","g_lpips_gain_best_src","g_rsr"]: row[k]=float("nan") row["g_valid_patch_count"]=0; row["g_success_patch_count"]=0 rows.append(row) if (i+1)%10==0 or i==0 or i+1==len(recs): print(f"[{i+1:04d}/{len(recs):04d}] {row['dataset']} | {row['method']} | {row['sample_id']} | A/B/AB/G/U={row['a_raw_ratio']:.3f}/{row['b_raw_ratio']:.3f}/{row['ab_raw_ratio']:.3f}/{row['g_raw_ratio']:.3f}/{row['uncertain_raw_ratio']:.3f}") write_csv(out/"region_metrics_per_image.csv",rows) write_csv(out/"region_metrics_summary.csv",summarize(rows)) print("[DONE]", out/"region_metrics_per_image.csv") print("[DONE]", out/"region_metrics_summary.csv") if __name__ == "__main__": main()#!/usr/bin/env python3 from __future__ import annotations import argparse, csv, math from collections import defaultdict from pathlib import Path from typing import Any import numpy as np import torch import torch.nn.functional as F from PIL import Image from skimage.metrics import structural_similarity ALIASES = { "dataset": ["dataset", "dataset_name", "set"], "method": ["method", "method_name", "model"], "sample_id": ["sample_id", "id", "name", "filename"], "a": ["a", "A", "image_a", "image_a_path", "a_path", "source_a", "input_a", "edit_image_0"], "b": ["b", "B", "image_b", "image_b_path", "b_path", "source_b", "input_b", "edit_image_1"], "gt": ["gt", "GT", "image", "target", "hq", "gt_path", "target_path", "image_path"], "pred": ["fused", "prediction", "pred", "output", "result", "fused_path", "prediction_path", "pred_path", "output_path"], "fa": ["focus_a", "focusA", "fa", "focus_map_a", "focus_a_path", "focus_map_a_path", "focus_image_a", "edit_image_2", "m_a"], "fb": ["focus_b", "focusB", "fb", "focus_map_b", "focus_b_path", "focus_map_b_path", "focus_image_b", "edit_image_3", "m_b"], } def parse_args(): p = argparse.ArgumentParser(description="Four-region MFIF evaluator: GT + No-GT protocols") p.add_argument("--manifest", required=True) p.add_argument("--output-dir", required=True) p.add_argument("--root", default="") p.add_argument("--sharp-threshold", type=float, default=0.70) p.add_argument("--blur-threshold", type=float, default=0.30) p.add_argument("--erode-radius", type=int, default=-1, help="-1 => max(2, round(min(H,W)/256))") p.add_argument("--patch-size", type=int, default=64) p.add_argument("--patch-stride", type=int, default=32) p.add_argument("--g-patch-min-coverage", type=float, default=0.80) p.add_argument("--g-rsr-psnr-margin", type=float, default=0.20) p.add_argument("--device", default="cuda") p.add_argument("--lpips-net", default="alex", choices=["alex", "vgg", "squeeze"]) p.add_argument("--no-lpips", action="store_true") for x in ["dataset", "method", "id", "a", "b", "gt", "pred", "focus-a", "focus-b"]: p.add_argument(f"--col-{x}", default="") return p.parse_args() def finite(x): try: return math.isfinite(float(x)) except Exception: return False def nanmean(xs): ys = [float(x) for x in xs if finite(x)] return float(np.mean(ys)) if ys else float("nan") def find_col(fields, explicit, key, required): if explicit: if explicit not in fields: raise KeyError(f"column {explicit!r} not found; columns={fields}") return explicit for c in ALIASES[key]: if c in fields: return c if required: raise KeyError(f"cannot detect column for {key}; columns={fields}") return None def resolve(root: Path, raw: Any): if raw is None: return None s = str(raw).strip() if not s or s.lower() in {"none", "nan", "null"}: return None p = Path(s) return p if p.is_absolute() else root / p def load_rgb(p: Path): if not p.is_file(): raise FileNotFoundError(p) return np.asarray(Image.open(p).convert("RGB"), np.float32) / 255.0 def load_gray(p: Path): if not p.is_file(): raise FileNotFoundError(p) if p.suffix.lower() == ".npy": x = np.squeeze(np.load(p)).astype(np.float32) if x.ndim != 2: raise ValueError(f"focus map must be 2D: {p} {x.shape}") if float(np.nanmax(x)) > 1.5: x /= 255.0 return np.clip(x, 0, 1) return np.asarray(Image.open(p).convert("L"), np.float32) / 255.0 def resize_rgb(x, hw, mode): h, w = hw if x.shape[:2] == (h, w): return x im = Image.fromarray(np.clip(np.round(x*255), 0, 255).astype(np.uint8), "RGB") return np.asarray(im.resize((w, h), mode), np.float32) / 255.0 def resize_gray(x, hw): h, w = hw if x.shape[:2] == (h, w): return x im = Image.fromarray(np.clip(np.round(x*255), 0, 255).astype(np.uint8), "L") return np.asarray(im.resize((w, h), Image.Resampling.BILINEAR), np.float32) / 255.0 def erode(mask, r): if r <= 0: return mask.astype(bool) x = torch.from_numpy(mask.astype(np.float32))[None,None] k = 2*r+1 y = 1 - F.max_pool2d(1-x, k, stride=1, padding=r) return (y[0,0].numpy() > .5) def gray(x): return (0.299*x[...,0] + 0.587*x[...,1] + 0.114*x[...,2]).astype(np.float32) SX = np.array([[-1,0,1],[-2,0,2],[-1,0,1]], np.float32)/8.0 SY = SX.T.copy() LAP = np.array([[0,1,0],[1,-4,1],[0,1,0]], np.float32) def conv(g, k): x = torch.from_numpy(g)[None,None] kk = torch.from_numpy(k)[None,None] return F.conv2d(x, kk, padding=(k.shape[0]//2, k.shape[1]//2))[0,0].numpy() def sobel(x): g = gray(x); gx = conv(g,SX); gy = conv(g,SY) return np.sqrt(gx*gx + gy*gy + 1e-12) def lapabs(x): return np.abs(conv(gray(x), LAP)) def blur_gray(g, sigma=1.5): r = max(1, int(round(3*sigma))) xs = torch.arange(-r, r+1, dtype=torch.float32) k = torch.exp(-(xs*xs)/(2*sigma*sigma)); k /= k.sum() x = torch.from_numpy(g)[None,None] x = F.conv2d(x, k[None,None,None,:], padding=(0,r)) x = F.conv2d(x, k[None,None,:,None], padding=(r,0)) return x[0,0].numpy() def hfabs(x): g = gray(x) return np.abs(g - blur_gray(g)) def masked_mean(x, m): if int(m.sum()) == 0: return float("nan") return float(np.mean(x[m])) def masked_mse(a,b,m): if int(m.sum()) == 0: return float("nan") return float(np.mean(((a-b)**2)[m,:])) def masked_mae(a,b,m): if int(m.sum()) == 0: return float("nan") return float(np.mean(np.abs(a-b)[m,:])) def psnr_from_mse(m): if not finite(m): return float("nan") if m <= 1e-12: return 120.0 return float(-10*math.log10(m)) def ssim_map(a,b): _, sm = structural_similarity(a,b,data_range=1.0,channel_axis=2,full=True, gaussian_weights=True,sigma=1.5,use_sample_covariance=False) if sm.ndim == 3: sm = sm.mean(2) return sm.astype(np.float32) class LP: def __init__(self, device="cuda", net="alex", enabled=True): self.enabled = enabled self.device = torch.device(device if device != "cuda" or torch.cuda.is_available() else "cpu") self.model = None if enabled: try: import lpips except Exception as e: raise RuntimeError("install lpips or use --no-lpips") from e self.model = lpips.LPIPS(net=net, spatial=True).to(self.device).eval() self.model.requires_grad_(False) def map(self,a,b): if not self.enabled: return None ta = torch.from_numpy(a.transpose(2,0,1))[None].to(self.device)*2-1 tb = torch.from_numpy(b.transpose(2,0,1))[None].to(self.device)*2-1 with torch.inference_mode(): y = self.model(ta,tb) y = F.interpolate(y, size=a.shape[:2], mode="bilinear", align_corners=False) return y[0,0].float().cpu().numpy() def masked(self, lm, m): if lm is None or int(m.sum()) == 0: return float("nan") return float(np.mean(lm[m])) def crop(self,a,b): if not self.enabled: return float("nan") ta = torch.from_numpy(a.transpose(2,0,1))[None].to(self.device)*2-1 tb = torch.from_numpy(b.transpose(2,0,1))[None].to(self.device)*2-1 with torch.inference_mode(): y = self.model(ta,tb) return float(y.mean().item()) def metrics(pred, ref, mask, sm, lm, lp): mse = masked_mse(pred,ref,mask) return { "psnr": psnr_from_mse(mse), "ssim": masked_mean(sm,mask), "lpips": lp.masked(lm,mask), "mae": masked_mae(pred,ref,mask), "mse": mse, } def put(row, prefix, d): for k,v in d.items(): row[f"{prefix}_{k}"] = v def regions(fa,fb,sharp,blur): AS, ABR = fa >= sharp, fa <= blur BS, BBR = fb >= sharp, fb <= blur r = { "a": AS & BBR, "b": ABR & BS, "ab": AS & BS, "g": ABR & BBR, } r["uncertain"] = ~(r["a"] | r["b"] | r["ab"] | r["g"]) return r def g_nogt(pred,a,b,m): if int(m.sum()) == 0: keys = ["sobel_pred","sobel_a","sobel_b","sobel_gain_best_src", "laplacian_pred","laplacian_a","laplacian_b","laplacian_gain_best_src", "highfreq_pred","highfreq_a","highfreq_b","highfreq_gain_best_src"] return {f"g_{k}": float("nan") for k in keys} sp,sa,sb = [masked_mean(z,m) for z in [sobel(pred),sobel(a),sobel(b)]] lp,la,lb = [masked_mean(z,m) for z in [lapabs(pred),lapabs(a),lapabs(b)]] hp,ha,hb = [masked_mean(z,m) for z in [hfabs(pred),hfabs(a),hfabs(b)]] return { "g_sobel_pred":sp, "g_sobel_a":sa, "g_sobel_b":sb, "g_sobel_gain_best_src":sp-max(sa,sb), "g_laplacian_pred":lp, "g_laplacian_a":la, "g_laplacian_b":lb, "g_laplacian_gain_best_src":lp-max(la,lb), "g_highfreq_pred":hp, "g_highfreq_a":ha, "g_highfreq_b":hb, "g_highfreq_gain_best_src":hp-max(ha,hb), } def patches(h,w,p,s): if h < p or w < p: return ys = list(range(0,h-p+1,s)); xs = list(range(0,w-p+1,s)) if ys[-1] != h-p: ys.append(h-p) if xs[-1] != w-p: xs.append(w-p) for y in ys: for x in xs: yield y,x def g_rsr(pred,a,b,gt,m,lp,patch,stride,mincov,margin): valid=success=0 h,w=m.shape for y,x in patches(h,w,patch,stride): mm=m[y:y+patch,x:x+patch] if float(mm.mean()) < mincov: continue pp=pred[y:y+patch,x:x+patch]; aa=a[y:y+patch,x:x+patch] bb=b[y:y+patch,x:x+patch]; gg=gt[y:y+patch,x:x+patch] pps=psnr_from_mse(masked_mse(pp,gg,mm)); aps=psnr_from_mse(masked_mse(aa,gg,mm)); bps=psnr_from_mse(masked_mse(bb,gg,mm)) if lp.enabled: pl=lp.crop(pp,gg); al=lp.crop(aa,gg); bl=lp.crop(bb,gg) lpok = pl < min(al,bl) else: lpok=True valid += 1 if pps > max(aps,bps)+margin and lpok: success += 1 return (success/valid if valid else float("nan")), valid, success def write_csv(path, rows): path.parent.mkdir(parents=True, exist_ok=True) keys=[]; seen=set() for r in rows: for k in r: if k not in seen: seen.add(k); keys.append(k) with path.open("w",newline="",encoding="utf-8") as f: w=csv.DictWriter(f,fieldnames=keys); w.writeheader(); w.writerows(rows) def summarize(rows): groups=defaultdict(list) for r in rows: groups[(r["dataset"],r["method"])].append(r) outs=[] skip={"dataset","method","sample_id","a_path","b_path","gt_path","pred_path","focus_a_path","focus_b_path", "g_valid_patch_count","g_success_patch_count"} for (ds,me),rs in groups.items(): o={"dataset":ds,"method":me,"n":len(rs)} nums=set() for r in rs: for k,v in r.items(): if k not in skip and isinstance(v,(int,float,np.integer,np.floating)): nums.add(k) for k in sorted(nums): o[k+"_mean"] = nanmean([r.get(k,float("nan")) for r in rs]) nv=sum(int(r.get("g_valid_patch_count",0)) for r in rs); ns=sum(int(r.get("g_success_patch_count",0)) for r in rs) o["g_rsr_pooled"] = ns/nv if nv else float("nan") o["g_valid_patch_count_total"] = nv; o["g_success_patch_count_total"] = ns outs.append(o) return outs def main(): args=parse_args(); mf=Path(args.manifest); out=Path(args.output_dir) root=Path(args.root) if args.root else mf.parent with mf.open("r",encoding="utf-8-sig",newline="") as f: rd=csv.DictReader(f); fields=rd.fieldnames or []; recs=list(rd) cd=find_col(fields,args.col_dataset,"dataset",False); cm=find_col(fields,args.col_method,"method",False); ci=find_col(fields,args.col_id,"sample_id",False) ca=find_col(fields,args.col_a,"a",True); cb=find_col(fields,args.col_b,"b",True); cp=find_col(fields,args.col_pred,"pred",True) cfa=find_col(fields,args.col_focus_a,"fa",True); cfb=find_col(fields,args.col_focus_b,"fb",True); cgt=find_col(fields,args.col_gt,"gt",False) print(f"[MANIFEST] {mf}\n[ROWS] {len(recs)}\n[COLUMNS] A={ca} B={cb} GT={cgt} PRED={cp} FA={cfa} FB={cfb}") lp=LP(args.device,args.lpips_net,not args.no_lpips); rows=[] for i,it in enumerate(recs): ap=resolve(root,it[ca]) bp=resolve(root,it[cb]) pp=resolve(root,it[cp]) fap=resolve(root,it[cfa]) fbp=resolve(root,it[cfb]) gtp=resolve(root,it[cgt]) if cgt else None mode=str(it.get("fused_mode","")).strip().lower() virtual_pred=None if mode in ( "avgblend", "avg_blend", "avg blend", ): virtual_pred="avgblend" elif mode in ( "no_generation", "nogeneration", "w/o generation", "wo generation", ): virtual_pred="nogeneration" if virtual_pred is None: if pp is None: raise RuntimeError( f"row {i}: missing fused path method={it.get('method')} mode={mode}" ) if any(x is None for x in [ap,bp,fap,fbp]): raise RuntimeError( f"row {i}: missing required path method={it.get('method')} mode={mode}" ) a=load_rgb(ap); h,w=a.shape[:2] b=resize_rgb(load_rgb(bp),(h,w),Image.Resampling.BICUBIC) if virtual_pred=="avgblend": pred=0.5*(a+b) elif virtual_pred=="nogeneration": pred=a.copy() else: pred=resize_rgb(load_rgb(pp),(h,w),Image.Resampling.BICUBIC) fa=resize_gray(load_gray(fap),(h,w)); fb=resize_gray(load_gray(fbp),(h,w)) gt=resize_rgb(load_rgb(gtp),(h,w),Image.Resampling.LANCZOS) if gtp is not None and gtp.is_file() else None raw=regions(fa,fb,args.sharp_threshold,args.blur_threshold) er=args.erode_radius if args.erode_radius>=0 else max(2,int(round(min(h,w)/256.0))) masks={k:(erode(v,er) if k!="uncertain" else v) for k,v in raw.items()} row={ "dataset":it[cd] if cd else "dataset", "method":it[cm] if cm else "method", "sample_id":it[ci] if ci else pp.stem, "a_path":str(ap),"b_path":str(bp),"gt_path":str(gtp) if gtp else "","pred_path":str(pp),"focus_a_path":str(fap),"focus_b_path":str(fbp), "height":h,"width":w,"erode_radius":er, "a_raw_ratio":float(raw["a"].mean()),"b_raw_ratio":float(raw["b"].mean()),"ab_raw_ratio":float(raw["ab"].mean()),"g_raw_ratio":float(raw["g"].mean()),"uncertain_raw_ratio":float(raw["uncertain"].mean()), "a_eval_ratio":float(masks["a"].mean()),"b_eval_ratio":float(masks["b"].mean()),"ab_eval_ratio":float(masks["ab"].mean()),"g_eval_ratio":float(masks["g"].mean()), "a_eval_pixels":int(masks["a"].sum()),"b_eval_pixels":int(masks["b"].sum()),"ab_eval_pixels":int(masks["ab"].sum()),"g_eval_pixels":int(masks["g"].sum()), } # No-GT A/B/AB preservation-transfer protocol. sma=ssim_map(pred,a); smb=ssim_map(pred,b); lma=lp.map(pred,a); lmb=lp.map(pred,b) put(row,"a_src",metrics(pred,a,masks["a"],sma,lma,lp)) put(row,"b_src",metrics(pred,b,masks["b"],smb,lmb,lp)) put(row,"ab_src_a",metrics(pred,a,masks["ab"],sma,lma,lp)) put(row,"ab_src_b",metrics(pred,b,masks["ab"],smb,lmb,lp)) preserve=masks["a"]|masks["ab"] put(row,"preserve_src",metrics(pred,a,preserve,sma,lma,lp)) row.update(g_nogt(pred,a,b,masks["g"])) if gt is not None: smg=ssim_map(pred,gt); lmg=lp.map(pred,gt) for reg in ["a","b","ab","g"]: put(row,f"{reg}_gt",metrics(pred,gt,masks[reg],smg,lmg,lp)) row["g_sobel_error"] = masked_mean(np.abs(sobel(pred)-sobel(gt)),masks["g"]) row["g_laplacian_error"] = masked_mean(np.abs(lapabs(pred)-lapabs(gt)),masks["g"]) smagt=ssim_map(a,gt); smbgt=ssim_map(b,gt); lmagt=lp.map(a,gt); lmbgt=lp.map(b,gt) ga=metrics(a,gt,masks["g"],smagt,lmagt,lp); gb=metrics(b,gt,masks["g"],smbgt,lmbgt,lp) for k,v in ga.items(): row[f"g_src_a_gt_{k}"]=v for k,v in gb.items(): row[f"g_src_b_gt_{k}"]=v row["g_psnr_gain_best_src"] = row["g_gt_psnr"]-max(ga["psnr"],gb["psnr"]) if finite(row["g_gt_psnr"]) and finite(ga["psnr"]) and finite(gb["psnr"]) else float("nan") row["g_lpips_gain_best_src"] = min(ga["lpips"],gb["lpips"])-row["g_gt_lpips"] if finite(row["g_gt_lpips"]) and finite(ga["lpips"]) and finite(gb["lpips"]) else float("nan") rsr,nv,ns=g_rsr(pred,a,b,gt,masks["g"],lp,args.patch_size,args.patch_stride,args.g_patch_min_coverage,args.g_rsr_psnr_margin) row["g_rsr"]=rsr; row["g_valid_patch_count"]=nv; row["g_success_patch_count"]=ns else: for reg in ["a","b","ab","g"]: for k in ["psnr","ssim","lpips","mae","mse"]: row[f"{reg}_gt_{k}"]=float("nan") for k in ["g_sobel_error","g_laplacian_error","g_psnr_gain_best_src","g_lpips_gain_best_src","g_rsr"]: row[k]=float("nan") row["g_valid_patch_count"]=0; row["g_success_patch_count"]=0 rows.append(row) if (i+1)%10==0 or i==0 or i+1==len(recs): print(f"[{i+1:04d}/{len(recs):04d}] {row['dataset']} | {row['method']} | {row['sample_id']} | A/B/AB/G/U={row['a_raw_ratio']:.3f}/{row['b_raw_ratio']:.3f}/{row['ab_raw_ratio']:.3f}/{row['g_raw_ratio']:.3f}/{row['uncertain_raw_ratio']:.3f}") write_csv(out/"region_metrics_per_image.csv",rows) write_csv(out/"region_metrics_summary.csv",summarize(rows)) print("[DONE]", out/"region_metrics_per_image.csv") print("[DONE]", out/"region_metrics_summary.csv") if __name__ == "__main__": main()